// Behavioural parity with the TS reference (Fixtures/core-parity.json, generated by
// scripts/gen-core-parity.mts): matching, CSV, search, account names, titles, throttle, generator.
import Foundation
import XCTest

@testable import VaultKit

final class ParityTests: XCTestCase {
  let psl = PublicSuffixList.shared
  var f: [String: Any] = [:]

  override func setUpWithError() throws {
    let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("Fixtures/core-parity.json")
    f = try XCTUnwrap(try JSONSerialization.jsonObject(with: try Data(contentsOf: url)) as? [String: Any])
  }

  func cases(_ k: String) throws -> [[String: Any]] { try XCTUnwrap(f[k] as? [[String: Any]]) }

  func testHostsAndUrls() throws {
    for c in try cases("toAsciiHost") {
      let input = c["input"] as! String
      XCTAssertEqual(Punycode.toAsciiHost(input), c["output"] as? String, "toAsciiHost(\(input.debugDescription))")
    }
    for c in try cases("parseUrl") {
      let input = c["input"] as! String
      let expected = (c["output"] as? [String: String]).map { ParsedUrl(scheme: $0["scheme"]!, host: $0["host"]!) }
      XCTAssertEqual(Matcher.parseUrl(input), expected, "parseUrl(\(input.debugDescription))")
      XCTAssertEqual(Matcher.hostOfStoredUrl(input), c["storedHost"] as? String, "hostOfStoredUrl(\(input.debugDescription))")
    }
    for c in try cases("registrableDomain") {
      let input = c["input"] as! String
      XCTAssertEqual(psl.registrableDomain(input), c["output"] as? String, "registrableDomain(\(input))")
    }
    XCTAssertGreaterThan(psl.size, 9000)
  }

  func testMatch() throws {
    for c in try cases("match") {
      let entries = (c["entries"] as! [[String: Any]]).map { e in
        MatchEntry(
          id: e["id"] as! String,
          urls: (e["urls"] as! [[String: String]]).map { UrlEntry(url: $0["url"]!, match: $0["match"]!) },
          lastUsedAt: e["lastUsedAt"] as? String, trashedAt: e["trashedAt"] as? String)
      }
      let got = Matcher.match(psl, requestUrl: c["request"] as! String, entries: entries)
      let expected = (c["output"] as! [[String: Any]]).map {
        MatchCandidate(id: $0["id"] as! String, rank: MatchRank(rawValue: $0["rank"] as! String)!, urlIndex: $0["urlIndex"] as! Int, requestHost: $0["requestHost"] as! String)
      }
      XCTAssertEqual(got, expected, c["request"] as! String)
    }
  }

  func testCsv() throws {
    for (i, c) in try cases("csv").enumerated() {
      let input = c["input"] as! String
      if let code = c["rows"] as? String {
        XCTAssertThrowsError(try CsvImport.parse(input), "rows #\(i)") { XCTAssertEqual(($0 as? VaultCoreError)?.code.rawValue, code) }
      } else {
        XCTAssertEqual(try CsvImport.parse(input), c["rows"] as! [[String]], "rows #\(i)")
      }
      if let code = c["result"] as? String {
        XCTAssertThrowsError(try CsvImport.parseImport(input), "import #\(i)") { XCTAssertEqual(($0 as? VaultCoreError)?.code.rawValue, code) }
        continue
      }
      let r = c["result"] as! [String: Any]
      let got = try CsvImport.parseImport(input)
      XCTAssertEqual(got.format.rawValue, r["format"] as! String, "format #\(i)")
      XCTAssertEqual(got.drafts, (r["drafts"] as! [[String: Any]]).map(draft), "drafts #\(i)")
      let skipped = (r["skipped"] as! [[String: Any]]).map { "\($0["row"]!):\($0["reason"]!)" }
      XCTAssertEqual(got.skipped.map { "\($0.row):\($0.reason.rawValue)" }, skipped, "skipped #\(i)")
    }
    let d = f["duplicates"] as! [String: Any]
    let drafts = (d["drafts"] as! [[String: Any]]).map(draft)
    let existing = (d["existing"] as! [[String: Any]]).map {
      (username: $0["username"] as! String, urls: ($0["urls"] as! [[String: String]]).map { UrlEntry(url: $0["url"]!, match: $0["match"]!) })
    }
    XCTAssertEqual(CsvImport.findDuplicates(psl, drafts: drafts, existing: existing), d["output"] as! [Int])
  }

  func draft(_ o: [String: Any]) -> CsvLoginDraft {
    CsvLoginDraft(
      title: o["title"] as! String, username: o["username"] as! String, password: o["password"] as! String,
      urls: (o["urls"] as! [[String: String]]).map { UrlEntry(url: $0["url"]!, match: $0["match"]!) },
      notes: o["notes"] as! String, favorite: o["favorite"] as! Bool)
  }

  func testSearchNamesTitlesThrottle() throws {
    for c in try cases("search") {
      XCTAssertEqual(Search.matches(c["query"] as! String, c["haystacks"] as! [String]), c["output"] as! Bool, c["query"] as! String)
    }
    for c in try cases("nfkc") {
      let input = c["input"] as! String
      XCTAssertEqual(input.nfkc.unicodeScalars.map(\.value), (c["output"] as! String).unicodeScalars.map(\.value), "nfkc(\(input))")
      XCTAssertEqual(Keys.passwordBytes(input), Array((c["output"] as! String).utf8))
    }
    for c in try cases("accountName") {
      let o = c["output"] as! [String: Any]
      let got = AccountName.normalize(c["input"] as! String)
      switch got {
      case let .success(n): XCTAssertEqual(o["name"] as? String, n, c["input"] as! String)
      case let .failure(e): XCTAssertEqual(o["reason"] as? String, e.rawValue, c["input"] as! String)
      }
    }
    let at = ISODate.parse("2026-11-14T23:59:59.999Z")!
    for c in try cases("conflictTitle") {
      XCTAssertEqual(Conflict.copyTitle(c["input"] as! String, now: at), c["output"] as! String)
    }
    for c in try cases("throttle") {
      XCTAssertEqual(Throttle.waitSec(c["failed"] as! Int), c["wait"] as! Int)
    }
  }

  func testGenerator() throws {
    for c in try cases("generator") {
      let o = c["options"] as! [String: Any]
      let opts = GeneratorOptions(
        length: o["length"] as! Int, upper: o["upper"] as! Bool, lower: o["lower"] as! Bool, digits: o["digits"] as! Bool,
        symbols: o["symbols"] as! Bool, excludeAmbiguous: o["excludeAmbiguous"] as! Bool)
      let det = DeterministicCrypto()
      for b in c["blocks"] as! [String] { det.enqueueRandom(try Hex.decode(b)) }
      XCTAssertEqual(try Generator.generate(det, opts), c["password"] as! String)
      XCTAssertTrue(det.drained)
    }
  }
}
